{"code":"def transform(grid):
    g=[r[:] for r in grid]
    h=len(g); w=len(g[0])
    # Bars are bottom-aligned vertical objects.  A 8-bar followed two columns later
    # by a 2-bar indicates the next (two-column) position, whose bar has height
    # equal to their height difference and color 5.
    bars={}
    for c in range(w):
        cells=[r for r in range(h) if grid[r][c]!=7]
        if cells and cells==list(range(min(cells),h)) and len(set(grid[r][c] for r in cells))==1:
            bars[c]=(grid[cells[0]][c],len(cells))
    for c,(col,n) in list(bars.items()):
        if col==8 and c+2 in bars and bars[c+2][0]==2:
            m=max(0,n-bars[c+2][1])
            for r in range(h-m,h):
                if g[r][c+4]==7: g[r][c+4]=5
    return g"}

