{"code":"def transform(grid):
    out=[r[:] for r in grid]
    h=len(grid); w=len(grid[0])
    # The long 8 stroke determines the height of the new stroke; it is
    # continued two columns beyond the terminal 2 stroke, one cell shorter.
    cols8=[]; cols2=[]
    for c in range(w):
        a=[r for r in range(h) if grid[r][c]==8]
        b=[r for r in range(h) if grid[r][c]==2]
        if a: cols8.append((c,a))
        if b: cols2.append((c,b))
    if cols8 and cols2:
        n=max(len(a) for c,a in cols8)-1
        c=max(c for c,a in cols2)+2
        if c<w and n>0:
            for r in range(h-n,h):
                if out[r][c]==7: out[r][c]=5
    return out"}

